static void inspectAllFieldRules(JCVariableDecl fieldDecl) {
	fieldRuleSkipDollarPrefix(fieldDecl);
	fieldRuleSkipStatic(fieldDecl);
	fieldRuleSkipFinal(fieldDecl);
	fieldRuleSkipTransient(fieldDecl);
	fieldRuleSkipVolatile(fieldDecl);
	fieldRuleSkipPublic(fieldDecl);
	fieldRuleRequirePrivate(fieldDecl);
	fieldRuleRequireFinal(fieldDecl);
	fieldRuleRequireInitializer(fieldDecl);
	fieldRuleSkipAbstract(fieldDecl);
}


static boolean innerTypeSymbolHasClassType(JCClassDecl innerClassDecl) {
	if (innerClassDecl == null) {
		return false;
	}
	ClassSymbol innerClassSymbol = innerClassDecl.sym;
	if (innerClassSymbol == null) {
		return false;
	}
	if (innerClassSymbol.type instanceof ClassType) {
		return true;
	}
	return false;
}


static boolean innerTypeNeedsStaticMark(JCClassDecl innerClassDecl) {
	if (innerClassDecl == null) {
		return false;
	}
	boolean alreadyStatic = typeDeclarationHasStaticFlag(innerClassDecl);
	if (alreadyStatic) {
		return false;
	}
	return true;
}


